INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `VerifiedBuild`) VALUES
(50508, 'Hello Karl, it has been a long time, and I wanted to reach out in assurance that I am still alive, and kicking. It has been forever since we have seen, and I am eager to see you once again.\n\nAfter departing from Kul Tiras, the fleet spent an extended amount of time at sea. As of recently we were attacked and the ship was destroyed and now we currently reside on the Isle of Lapidis off the coast of Stranglethorn Vale. When the ship is repaired, I will be returning home, and will stop by to say hello like old times.\n\nYour Older Brother Arnold.', 0, 0),
(50509, 'Little brother, it has been an eternity since we have seen one another. I am currently stranded on an island called Lapidis off the coast of Stranglethorn Vale near the south seas with others in the fleet. We call this place home, and have for a while now, and are repairing our ship.\n\nWhen repairs are done, I will be stopping to see you and Karl. I look forward to this day very well, and hope you are doing well.\n\nYour Older Brother Arnold.', 0, 0);
